WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT id, device_code, temp_c, pressure, status_bits, firmware, is_new_session, session_no, CASE WHEN device_code RLIKE '^(DV-03|DV-01)$' THEN 'PRIORITY' ELSE 'CORE' END AS device_code_zone FROM sessionized ORDER BY pressure DESC NULLS LAST
